ids = ["BQ-017","BQ-018","BQ-019","BQ-020","BQ-021","BQ-022","BQ-023","BQ-024","BQ-025",
       "BZ-016","BZ-019","BZ-020","BZ-021","BZ-022","BZ-023","BZ-024","BZ-025","BZ-026","BZ-027","BZ-028"]
assert set(ids) == set(P.keys()) and len(ids) == 20
written = []
for cid in ids:
    d = P[cid]
    rec = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
           "confidence": d["confidence"], "trigger": d["trigger"]}
    p = os.path.join(BASE, cid + ".json")
    with open(p, "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
    written.append(p)

# 自验：回读断言
assert len(written) == len(ids), (len(written), len(ids))
cm = ru = disp = 0
for cid in ids:
    p = os.path.join(BASE, cid + ".json")
    with open(p, encoding="utf-8") as f:
        r = json.load(f)
    assert r["case_id"] == cid, cid
    for k in ("case_id","prediction_text","basis","confidence","trigger"):
        assert k in r and r[k] not in (None, ""), (cid, k)
    assert isinstance(r["confidence"], (int, float)) and 0 <= r["confidence"] <= 1
    t = r["trigger"]
    for b in ("changed_main","reserve_used","disputed"):
        assert isinstance(t[b], bool), (cid, b)
    assert isinstance(t["reason"], str)
    cm += t["changed_main"]; ru += t["reserve_used"]; disp += t["disputed"]
print(f"OK files={len(written)} changed_main={cm} reserve_used={ru} disputed={disp}")
